import type { GestureRecognizer } from "@mediapipe/tasks-vision";
import type { CannedGesture, GestureAction, GestureConfig, GestureHud, GestureSource } from "@/contracts";
import { GestureEngine, type EngineFrame } from "./engine";

type HudError = NonNullable<GestureHud["error"]>;
const ALLOW: CannedGesture[] = ["Open_Palm", "Closed_Fist", "Thumb_Up", "Thumb_Down", "Victory"];
const HUD_INTERVAL_MS = 100; // ≤ 10 Hz (contract)

function idleHud(state: GestureHud["state"], error?: HudError): GestureHud {
  return { state, pose: "None", holdProgress: 0, pendingAction: null, armedRemainingMs: 0, lastAction: null, hint: null, fps: 0, error };
}

/** Main-thread MediaPipe loop (SPEC §11.5). Camera frames stay in the browser; WASM + model are self-hosted. */
export class MediaPipeGestureSource implements GestureSource {
  private engine: GestureEngine;
  private actionCbs = new Set<(a: GestureAction) => void>();
  private hudCbs = new Set<(h: GestureHud) => void>();
  private recognizer: GestureRecognizer | null = null;
  private stream: MediaStream | null = null;
  private video: HTMLVideoElement | null = null;
  private raf = 0;
  private aborted = false;
  private lastVideoTime = -1;
  private lastProcessed = 0;
  private lastHandAt = 0;
  private lastHudAt = 0;
  private frames: number[] = [];
  /** Latest landmarks, for the NEXT_PUBLIC_GESTURE_DEBUG overlay. */
  landmarks: Array<{ x: number; y: number }> | null = null;

  constructor(private config: GestureConfig) {
    this.engine = new GestureEngine(config);
  }

  setConfig(c: GestureConfig) {
    this.config = c;
    this.engine.setConfig(c);
  }

  async start(video: HTMLVideoElement): Promise<void> {
    this.aborted = false;
    this.video = video;
    this.emitHud(idleHud("loading"));

    if (!navigator.mediaDevices?.getUserMedia) return this.emitHud(idleHud("error", "InsecureContext"));

    // Ask for the camera and load the model in parallel; either can fail independently.
    const camera = navigator.mediaDevices
      .getUserMedia({ video: { facingMode: "user", width: { ideal: 640 }, height: { ideal: 480 }, frameRate: { ideal: 30 } }, audio: false })
      .then((s) => ({ ok: true as const, s }))
      .catch((e: DOMException) => ({ ok: false as const, e }));

    try {
      this.recognizer = await this.createRecognizer();
    } catch {
      (await camera).ok && (await camera as { s: MediaStream }).s.getTracks().forEach((t) => t.stop());
      if (!this.aborted) this.emitHud(idleHud("error", "ModelLoadFailed"));
      return;
    }

    const cam = await camera;
    if (this.aborted) {
      if (cam.ok) cam.s.getTracks().forEach((t) => t.stop());
      this.recognizer?.close();
      this.recognizer = null;
      return;
    }
    if (!cam.ok) {
      const name = cam.e.name === "NotFoundError" || cam.e.name === "NotReadableError" ? cam.e.name : "NotAllowedError";
      return this.emitHud(idleHud(name === "NotAllowedError" ? "permission_needed" : "error", name));
    }

    this.stream = cam.s;
    video.srcObject = cam.s;
    video.muted = true;
    video.playsInline = true;
    await video.play().catch(() => {});
    if (this.aborted) return this.stop();

    this.engine.reset();
    this.lastHandAt = performance.now();
    document.addEventListener("visibilitychange", this.onVisibility);
    this.emitHud(idleHud("no_hand"));
    this.raf = requestAnimationFrame(this.loop);
  }

  stop() {
    this.aborted = true;
    cancelAnimationFrame(this.raf);
    document.removeEventListener("visibilitychange", this.onVisibility);
    this.stream?.getTracks().forEach((t) => t.stop());
    this.stream = null;
    if (this.video) this.video.srcObject = null;
    this.recognizer?.close();
    this.recognizer = null;
    this.landmarks = null;
    this.emitHud(idleHud("off"));
  }

  onAction(cb: (a: GestureAction) => void) {
    this.actionCbs.add(cb);
    return () => void this.actionCbs.delete(cb);
  }

  onHud(cb: (h: GestureHud) => void) {
    this.hudCbs.add(cb);
    return () => void this.hudCbs.delete(cb);
  }

  private async createRecognizer(): Promise<GestureRecognizer> {
    const { FilesetResolver, GestureRecognizer } = await import("@mediapipe/tasks-vision");
    const fileset = await FilesetResolver.forVisionTasks("/mediapipe/wasm");
    const make = (delegate: "GPU" | "CPU") =>
      GestureRecognizer.createFromOptions(fileset, {
        baseOptions: { modelAssetPath: "/models/gesture_recognizer.task", delegate },
        runningMode: "VIDEO",
        numHands: 1,
        cannedGesturesClassifierOptions: { scoreThreshold: this.config.classifierScoreThreshold, categoryAllowlist: ALLOW },
      });
    try {
      return await make(this.config.delegate);
    } catch (e) {
      if (this.config.delegate === "CPU") throw e;
      return make("CPU"); // GPU unavailable (or blocklisted): fall back
    }
  }

  private onVisibility = () => {
    cancelAnimationFrame(this.raf);
    if (document.visibilityState === "visible" && this.recognizer && !this.aborted) {
      this.engine.reset(); // never resume mid-hold after a pause
      this.raf = requestAnimationFrame(this.loop);
    }
  };

  private loop = () => {
    if (this.aborted || !this.recognizer || !this.video) return;
    this.raf = requestAnimationFrame(this.loop);

    const now = performance.now();
    const idle = now - this.lastHandAt > this.config.idleAfterMs;
    const fps = idle ? this.config.idleFps : this.config.targetFps;
    const v = this.video;
    if (v.readyState < 2 || v.currentTime === this.lastVideoTime || now - this.lastProcessed < 1000 / fps) return;
    this.lastVideoTime = v.currentTime;
    this.lastProcessed = now;

    let frame: EngineFrame = { hand: null };
    try {
      const r = this.recognizer.recognizeForVideo(v, now);
      const lm = r.landmarks[0];
      const g = r.gestures[0]?.[0];
      if (lm) frame = { hand: { landmarks: lm, gesture: (g?.categoryName || "None") as CannedGesture, score: g?.score ?? 0 } };
      this.landmarks = lm ?? null;
    } catch {
      return; // a single bad frame is not fatal
    }
    if (frame.hand) this.lastHandAt = now;

    this.frames.push(now);
    while (this.frames.length && this.frames[0] < now - 1000) this.frames.shift();

    for (const a of this.engine.update(frame, now)) this.actionCbs.forEach((cb) => cb(a));
    if (now - this.lastHudAt >= HUD_INTERVAL_MS) {
      this.lastHudAt = now;
      this.emitHud({ ...this.engine.hud(now), fps: this.frames.length });
    }
  };

  private emitHud(h: GestureHud) {
    this.hudCbs.forEach((cb) => cb(h));
  }
}

import type { GestureConfig } from "@/contracts";
import { DEFAULT_GESTURE_CONFIG } from "./config";

// Per-device cook-mode settings in localStorage (decided: no DB column, no /api/me change).
export interface CookPrefs {
  gesture: GestureConfig;
  showCamera: boolean;
  autoRead: boolean;
}

const KEY = "mise.cook-prefs";
export const DEFAULT_PREFS: CookPrefs = { gesture: DEFAULT_GESTURE_CONFIG, showCamera: true, autoRead: false };

export function loadPrefs(): CookPrefs {
  try {
    const saved = JSON.parse(localStorage.getItem(KEY) ?? "null") as Partial<CookPrefs> | null;
    if (!saved) return DEFAULT_PREFS;
    // Merge over defaults so new config fields added later still get values.
    return { ...DEFAULT_PREFS, ...saved, gesture: { ...DEFAULT_GESTURE_CONFIG, ...saved.gesture } };
  } catch {
    return DEFAULT_PREFS;
  }
}

export function savePrefs(p: CookPrefs) {
  try {
    localStorage.setItem(KEY, JSON.stringify(p));
  } catch {}
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { CookingController, GestureAction, GestureConfig, GestureHud } from "@/contracts";
import { Button } from "@/components/ui";
import { click } from "@/features/cook/alarm";
import { MediaPipeGestureSource } from "./MediaPipeGestureSource";

const DEBUG = process.env.NEXT_PUBLIC_GESTURE_DEBUG === "true";

const DONE: Record<GestureAction, string> = {
  ARM: "Ready",
  DISARM: "Hands-free paused",
  NEXT_STEP: "Next step",
  PREV_STEP: "Previous step",
  SCROLL_UP: "Scrolled up",
  SCROLL_DOWN: "Scrolled down",
  TIMER_TOGGLE: "Timer toggled",
  SPEAK_TOGGLE: "Read aloud toggled",
};
const HOLDING: Partial<Record<GestureAction, string>> = {
  TIMER_TOGGLE: "Hold fist…",
  SPEAK_TOGGLE: "Hold victory…",
  SCROLL_UP: "Scrolling up",
  SCROLL_DOWN: "Scrolling down",
  ARM: "Hold your palm…",
};
const ERRORS: Record<NonNullable<GestureHud["error"]>, string> = {
  NotAllowedError: "Camera blocked. Use the buttons or keyboard.",
  NotFoundError: "No camera found. Use the buttons or keyboard.",
  NotReadableError: "The camera is in use by another app. Use the buttons or keyboard.",
  InsecureContext: "Hands-free needs HTTPS. Use the buttons or keyboard.",
  ModelLoadFailed: "Hands-free couldn't load. Use the buttons or keyboard.",
};
const LEGEND = [
  ["✋", "Hold palm: start"],
  ["👈", "Swipe: next / back"],
  ["👍", "Thumb up/down: scroll"],
  ["✊", "Fist: timer"],
  ["✌️", "Victory: read aloud"],
];

function chip(h: GestureHud): string {
  if (h.error) return ERRORS[h.error];
  switch (h.state) {
    case "off":
    case "loading":
      return "Starting camera…";
    case "permission_needed":
      return ERRORS.NotAllowedError;
    case "error":
      return ERRORS.ModelLoadFailed;
    case "no_hand":
      return "Show your palm to start";
    case "hand_seen":
      return h.pose === "Open_Palm" ? "Hold your palm…" : "Show your palm to start";
    case "armed":
      return h.armedRemainingMs > 0 ? `Ready · ${Math.ceil(h.armedRemainingMs / 1000)} s` : "Ready";
    case "holding":
      return (h.pendingAction && HOLDING[h.pendingAction]) ?? "Hold…";
    case "cooldown":
      return h.lastAction ? `${DONE[h.lastAction.action]} ✓` : "Ready";
  }
}

/** Hands-free mode: camera + MediaPipe → CookingController, with the HUD (SPEC §11.5–§11.6).
 *  Load with next/dynamic({ ssr: false }). Unmounting stops the camera. */
export default function GestureController({
  controller,
  config,
  showCamera,
  announce,
  onExit,
}: {
  controller: CookingController;
  config: GestureConfig;
  showCamera: boolean;
  announce: (text: string) => void;
  onExit: () => void;
}) {
  const video = useRef<HTMLVideoElement>(null);
  const canvas = useRef<HTMLCanvasElement>(null);
  const source = useRef<MediaPipeGestureSource | null>(null);
  const [hud, setHud] = useState<GestureHud | null>(null);
  const [flash, setFlash] = useState(0);
  const [attempt, setAttempt] = useState(0);
  // Latest props for the long-lived action callback.
  const latest = useRef({ controller, announce });
  useEffect(() => {
    latest.current = { controller, announce };
  });

  useEffect(() => {
    const v = video.current;
    if (!v) return;
    const src = new MediaPipeGestureSource(config);
    source.current = src;
    const offHud = src.onHud((h) => {
      setHud(h);
      if (DEBUG) drawLandmarks(canvas.current, src.landmarks);
    });
    const offAction = src.onAction((a) => {
      const { controller: c, announce: say } = latest.current;
      c.source = "gesture";
      if (a === "NEXT_STEP") c.nextStep();
      else if (a === "PREV_STEP") c.prevStep();
      else if (a === "SCROLL_UP") c.scroll("up");
      else if (a === "SCROLL_DOWN") c.scroll("down");
      else if (a === "TIMER_TOGGLE") c.toggleTimer();
      else if (a === "SPEAK_TOGGLE") c.toggleSpeak();
      c.source = undefined;
      if (a !== "NEXT_STEP" && a !== "PREV_STEP") say(DONE[a]); // step changes announce themselves
      if (a !== "SCROLL_UP" && a !== "SCROLL_DOWN") {
        click();
        setFlash(Date.now());
      }
    });
    void src.start(v);
    return () => {
      offHud();
      offAction();
      src.stop();
      source.current = null;
    };
    // config changes go through setConfig below; restart only on retry.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [attempt]);

  useEffect(() => {
    source.current?.setConfig(config);
  }, [config]);

  useEffect(() => {
    if (!flash) return;
    const t = setTimeout(() => setFlash(0), 250);
    return () => clearTimeout(t);
  }, [flash]);

  const failed = hud?.state === "permission_needed" || hud?.state === "error";
  const ring = 2 * Math.PI * 18;

  return (
    <>
      {/* Edge flash for fired actions: the cook is often looking at the pan, not the screen. */}
      <div
        aria-hidden
        className={`pointer-events-none fixed inset-0 z-30 border-[6px] border-accent transition-opacity duration-200 ${flash ? "opacity-100" : "opacity-0"}`}
      />

      <aside
        aria-label="Hands-free status"
        className="fixed bottom-44 right-3 z-20 w-56 max-w-[calc(100vw-1.5rem)] rounded-2xl border border-line bg-surface/95 p-3 text-sm shadow-xl backdrop-blur"
      >
        <div className={`relative overflow-hidden rounded-xl bg-black ${showCamera && !failed ? "" : "hidden"}`}>
          <video ref={video} className="aspect-[4/3] w-full -scale-x-100 object-cover" muted playsInline />
          {DEBUG && <canvas ref={canvas} width={320} height={240} className="absolute inset-0 h-full w-full" />}
        </div>

        <div className="mt-2 flex items-center gap-3">
          <svg viewBox="0 0 40 40" className="size-10 shrink-0 -rotate-90" aria-hidden>
            <circle cx="20" cy="20" r="18" fill="none" stroke="var(--line)" strokeWidth="4" />
            <circle
              cx="20"
              cy="20"
              r="18"
              fill="none"
              stroke="var(--accent)"
              strokeWidth="4"
              strokeDasharray={ring}
              strokeDashoffset={ring * (1 - (hud?.holdProgress ?? 0))}
            />
          </svg>
          <p className="font-semibold leading-tight" role="status">
            {hud ? chip(hud) : "Starting camera…"}
          </p>
        </div>

        {hud?.hint === "move_closer" && <p className="mt-1 text-warn">Move closer</p>}
        {hud?.hint === "more_light" && <p className="mt-1 text-warn">Turn on a light</p>}
        {hud?.hint === "one_hand_only" && <p className="mt-1 text-warn">One hand please</p>}
        {DEBUG && hud && <p className="mt-1 font-mono text-xs text-muted">{hud.fps} fps · {hud.pose}</p>}

        {failed ? (
          hud?.state === "permission_needed" && (
            <Button variant="secondary" className="mt-2 w-full" onClick={() => setAttempt((n) => n + 1)}>
              Try again
            </Button>
          )
        ) : (
          <ul className="mt-2 grid gap-0.5 text-xs text-muted">
            {LEGEND.map(([icon, text]) => (
              <li key={text}>
                <span aria-hidden>{icon}</span> {text}
              </li>
            ))}
          </ul>
        )}

        <div className="mt-2 flex items-center justify-between rounded-full bg-surface-2 py-1 pl-3 pr-1">
          <span className="text-xs font-semibold">{failed ? "Camera off" : "● Camera on"}</span>
          <Button variant="ghost" className="min-h-8 px-3 text-xs" onClick={onExit}>
            Turn off
          </Button>
        </div>
      </aside>
    </>
  );
}

function drawLandmarks(c: HTMLCanvasElement | null, lm: Array<{ x: number; y: number }> | null) {
  const ctx = c?.getContext("2d");
  if (!c || !ctx) return;
  ctx.clearRect(0, 0, c.width, c.height);
  ctx.fillStyle = "#7fc48f";
  for (const p of lm ?? []) ctx.fillRect((1 - p.x) * c.width - 2, p.y * c.height - 2, 4, 4); // mirrored like the video
}

